function global:prompt { $ts=Get-Date -Format "yyyy-MM-dd HH:mm:ss"; $loc=(Get-Location).Path; if($loc -like ($HOME+"*")){ $loc=$loc.Replace($HOME,"~") }; $admin=if(([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)){"ADMIN"}else{"USER"}; Write-Host ""; Write-Host ("[RUNEFORGE]["+$ts+"]") -ForegroundColor Magenta; Write-Host ("["+$loc+"]["+$admin+"]") -ForegroundColor DarkGray; return "⚡ PS> " }
